custom_css:
/* Midnight Professional Theme */
:root {
  --shadow-professional: 0 10px 40px -10px hsl(220 100% 10% / 0.4);
  --gradient-professional: linear-gradient(135deg, hsl(220 100% 65%), hsl(240 90% 55%));
}

.card {
  background: linear-gradient(135deg, hsl(220 30% 12% / 0.95), hsl(220 25% 8% / 0.98));
  border: 1px solid hsl(220 40% 18% / 0.6);
  box-shadow: var(--shadow-professional);
}

.nav-item:hover {
  background: var(--gradient-professional);
  box-shadow: 0 0 25px hsl(220 100% 65% / 0.3);
}

.chapter-card {
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.chapter-card:hover {
  transform: translateY(-8px) scale(1.02);
  box-shadow: 0 20px 50px -15px hsl(220 100% 30% / 0.4);
}

/* Sakura Elegance Theme */
:root {
  --gradient-sakura: linear-gradient(135deg, hsl(330 80% 70%), hsl(15 85% 65%));
  --shadow-sakura: 0 15px 35px -10px hsl(330 80% 40% / 0.3);
}

.hero-section {
  background: var(--gradient-sakura);
  position: relative;
}

.hero-section::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><circle cx="20" cy="20" r="2" fill="%23fff" opacity="0.1"/><circle cx="80" cy="40" r="1.5" fill="%23fff" opacity="0.15"/><circle cx="40" cy="80" r="2.5" fill="%23fff" opacity="0.08"/></svg>');
}

.manga-card {
  background: linear-gradient(135deg, hsl(330 30% 15% / 0.9), hsl(330 25% 12% / 0.95));
  border: 2px solid hsl(330 80% 70% / 0.2);
  box-shadow: var(--shadow-sakura);
}

.button {
  background: var(--gradient-sakura);
  box-shadow: 0 8px 20px hsl(330 80% 50% / 0.3);
}

/* Emerald Luxury Theme */
:root {
  --gradient-emerald: linear-gradient(135deg, hsl(160 85% 55%), hsl(140 80% 50%));
  --gradient-gold: linear-gradient(135deg, hsl(50 100% 75%), hsl(45 95% 65%));
  --shadow-luxury: 0 20px 60px -15px hsl(160 85% 25% / 0.4);
}

.premium-badge {
  background: var(--gradient-gold);
  color: hsl(50 50% 15%);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.card {
  background: linear-gradient(135deg, hsl(160 30% 12% / 0.95), hsl(160 25% 8% / 0.98));
  border: 1px solid hsl(160 85% 55% / 0.3);
  box-shadow: var(--shadow-luxury);
}

.navigation {
  backdrop-filter: blur(20px);
  background: hsl(160 20% 6% / 0.9);
  border-bottom: 2px solid var(--gradient-emerald);
}

.reader-controls {
  background: var(--gradient-emerald);
  box-shadow: 0 0 30px hsl(160 85% 40% / 0.4);
}

/* Royal Purple Theme */
:root {
  --gradient-royal: linear-gradient(135deg, hsl(280 90% 65%), hsl(260 85% 60%));
  --gradient-silver: linear-gradient(135deg, hsl(0 0% 85%), hsl(0 0% 75%));
  --shadow-royal: 0 15px 45px -10px hsl(280 90% 30% / 0.4);
}

.crown-element {
  background: var(--gradient-royal);
  position: relative;
}

.crown-element::before {
  content: '♔';
  position: absolute;
  top: -5px;
  right: -5px;
  color: hsl(50 95% 70%);
  font-size: 1.2em;
  text-shadow: 0 0 10px hsl(50 95% 70% / 0.6);
}

.manga-title {
  background: var(--gradient-royal);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  font-weight: 700;
}

.chapter-list {
  background: linear-gradient(180deg, hsl(280 30% 12%), hsl(280 25% 8%));
  border: 2px solid hsl(280 90% 65% / 0.2);
  box-shadow: var(--shadow-royal);
}

/* Arctic Minimal Theme */
:root {
  --gradient-arctic: linear-gradient(135deg, hsl(200 100% 60%), hsl(180 90% 55%));
  --shadow-minimal: 0 8px 25px -8px hsl(200 50% 50% / 0.15);
  --glass-effect: backdrop-filter: blur(20px);
}

.card {
  background: hsl(0 0% 100% / 0.8);
  var(--glass-effect);
  border: 1px solid hsl(200 30% 90%);
  box-shadow: var(--shadow-minimal);
}

.navigation {
  background: hsl(0 0% 100% / 0.9);
  var(--glass-effect);
  border-bottom: 1px solid hsl(200 30% 90%);
}

.button {
  background: var(--gradient-arctic);
  color: white;
  border: none;
  box-shadow: 0 4px 15px hsl(200 100% 60% / 0.3);
}

.manga-page {
  border-radius: 1rem;
  box-shadow: 0 10px 30px -10px hsl(200 50% 50% / 0.1);
}

body {
  background: linear-gradient(180deg, hsl(200 50% 98%), hsl(180 30% 96%));
}

/* Neon Cyberpunk Theme */
:root {
  --gradient-neon: linear-gradient(135deg, hsl(190 100% 50%), hsl(340 100% 60%));
  --glow-cyan: 0 0 20px hsl(190 100% 50% / 0.5);
  --glow-pink: 0 0 20px hsl(340 100% 60% / 0.5);
}

.cyber-grid {
  background-image: 
    linear-gradient(hsl(190 100% 50% / 0.1) 1px, transparent 1px),
    linear-gradient(90deg, hsl(190 100% 50% / 0.1) 1px, transparent 1px);
  background-size: 20px 20px;
}

.neon-text {
  color: hsl(190 100% 50%);
  text-shadow: var(--glow-cyan);
  animation: neon-flicker 2s infinite alternate;
}

@keyframes neon-flicker {
  0%, 100% { text-shadow: var(--glow-cyan); }
  50% { text-shadow: var(--glow-cyan), var(--glow-pink); }
}

.card {
  background: hsl(190 30% 8% / 0.9);
  border: 1px solid hsl(190 100% 50% / 0.3);
  box-shadow: 0 0 30px hsl(190 100% 50% / 0.2);
}

.button {
  background: var(--gradient-neon);
  box-shadow: var(--glow-cyan);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 600;
}

/* Vintage Sepia Theme */
:root {
  --gradient-vintage: linear-gradient(135deg, hsl(35 60% 50%), hsl(25 55% 45%));
  --paper-texture: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><filter id="paper"><feTurbulence baseFrequency="0.04" numOctaves="5" seed="2"/><feComponentTransfer><feFuncA type="discrete" tableValues="0 .5 .7 .8 .9 1"/></feComponentTransfer></filter><rect width="100" height="100" filter="url(%23paper)" fill="%23d4a574" opacity="0.1"/></svg>');
}

.vintage-paper {
  background: var(--paper-texture), linear-gradient(135deg, hsl(35 40% 20%), hsl(35 30% 15%));
  position: relative;
}

.vintage-paper::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: radial-gradient(circle at center, transparent 30%, hsl(35 30% 10% / 0.1) 100%);
}

.ornamental-border {
  border: 2px solid hsl(35 60% 50%);
  border-style: dashed;
  position: relative;
}

.chapter-title {
  font-family: serif;
  color: hsl(35 60% 70%);
  text-shadow: 2px 2px 4px hsl(35 30% 10% / 0.5);
}

.manga-cover {
  filter: sepia(30%) contrast(1.1) brightness(0.9);
  border: 3px solid hsl(35 60% 50%);
}

/* Coral Sunset Theme */
:root {
  --gradient-sunset: linear-gradient(135deg, hsl(15 85% 65%), hsl(25 80% 60%), hsl(35 75% 55%));
  --gradient-evening: linear-gradient(180deg, hsl(15 30% 8%), hsl(25 25% 6%));
  --shadow-warm: 0 15px 40px -10px hsl(15 85% 40% / 0.3);
}

.sunset-hero {
  background: var(--gradient-sunset);
  position: relative;
  overflow: hidden;
}

.sunset-hero::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: radial-gradient(ellipse at bottom, transparent 0%, hsl(15 30% 8% / 0.6) 100%);
}

.tropical-card {
  background: linear-gradient(135deg, hsl(15 40% 15% / 0.95), hsl(15 35% 12% / 0.98));
  border: 2px solid hsl(15 85% 65% / 0.3);
  box-shadow: var(--shadow-warm);
  backdrop-filter: blur(10px);
}

.wave-animation {
  animation: gentle-wave 3s ease-in-out infinite;
}

@keyframes gentle-wave {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-5px); }
}

body {
  background: var(--gradient-evening);
}

/* Monochrome Elite Theme */
:root {
  --gradient-silver: linear-gradient(135deg, hsl(0 0% 85%), hsl(0 0% 70%));
  --gradient-chrome: linear-gradient(135deg, hsl(0 0% 90%), hsl(0 0% 80%), hsl(0 0% 85%));
  --shadow-elite: 0 20px 50px -15px hsl(0 0% 0% / 0.4);
}

.chrome-finish {
  background: var(--gradient-chrome);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  font-weight: 700;
}

.elite-border {
  border: 2px solid;
  border-image: var(--gradient-silver) 1;
}

.card {
  background: linear-gradient(135deg, hsl(0 0% 15% / 0.95), hsl(0 0% 8% / 0.98));
  border: 1px solid hsl(0 0% 30%);
  box-shadow: var(--shadow-elite);
}

.manga-page {
  border: 3px solid hsl(0 0% 85%);
  box-shadow: 
    0 0 0 1px hsl(0 0% 70%),
    0 15px 35px -10px hsl(0 0% 0% / 0.3);
}

.premium-indicator {
  background: var(--gradient-silver);
  color: hsl(0 0% 10%);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

/* Aurora Mystical Theme */
:root {
  --gradient-aurora: linear-gradient(135deg, 
    hsl(120 70% 60%), 
    hsl(280 80% 65%), 
    hsl(340 75% 60%), 
    hsl(60 90% 70%));
  --aurora-glow: 0 0 30px hsl(120 70% 60% / 0.4);
}

.aurora-background {
  background: var(--gradient-aurora);
  background-size: 400% 400%;
  animation: aurora-shift 8s ease-in-out infinite;
}

@keyframes aurora-shift {
  0%, 100% { background-position: 0% 50%; }
  25% { background-position: 100% 50%; }
  50% { background-position: 50% 100%; }
  75% { background-position: 50% 0%; }
}

.mystical-glow {
  box-shadow: var(--aurora-glow);
  animation: mystical-pulse 3s ease-in-out infinite;
}

@keyframes mystical-pulse {
  0%, 100% { box-shadow: var(--aurora-glow); }
  50% { box-shadow: 0 0 40px hsl(280 80% 65% / 0.6); }
}

.card {
  background: linear-gradient(135deg, hsl(220 40% 12% / 0.9), hsl(220 35% 8% / 0.95));
  border: 2px solid transparent;
  background-clip: padding-box;
  position: relative;
}

.card::before {
  content: '';
  position: absolute;
  inset: 0;
  padding: 2px;
  background: var(--gradient-aurora);
  border-radius: inherit;
  mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  mask-composite: exclude;
}

.ethereal-text {
  background: var(--gradient-aurora);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: aurora-shift 8s ease-in-out infinite;
}
